import matter from "gray-matter";
import yaml from "js-yaml";

export interface FrontmatterParseSuccess {
  ok: true;
  data: Record<string, unknown>;
  content: string;
  /** 1-based line of the opening `---` */
  startLine: number;
  /** 1-based line of the closing `---` */
  endLine: number;
  hasFrontmatter: boolean;
}

export interface FrontmatterParseFailure {
  ok: false;
  error: string;
  /** 1-based line when known */
  line?: number;
  hasFrontmatter: boolean;
}

export type FrontmatterParseResult = FrontmatterParseSuccess | FrontmatterParseFailure;

const FRONTMATTER_OPEN = /^---[ \t]*\r?\n/;

/**
 * Parse YAML frontmatter from a markdown document.
 * Reports line numbers for YAML errors when possible.
 */
export function parseFrontmatter(source: string): FrontmatterParseResult {
  const open = source.match(FRONTMATTER_OPEN);
  if (!open) {
    return {
      ok: true,
      data: {},
      content: source,
      startLine: 1,
      endLine: 1,
      hasFrontmatter: false,
    };
  }

  const afterOpen = source.slice(open[0].length);
  const closeMatch = afterOpen.match(/\r?\n---[ \t]*(?:\r?\n|$)/);
  if (!closeMatch || closeMatch.index === undefined) {
    return {
      ok: false,
      error: "Unclosed YAML frontmatter block (missing closing ---)",
      line: 1,
      hasFrontmatter: true,
    };
  }

  const yamlText = afterOpen.slice(0, closeMatch.index);
  const startLine = 1;
  const yamlLineCount = yamlText.length === 0 ? 0 : yamlText.split(/\r?\n/).length;
  const endLine = startLine + 1 + yamlLineCount;

  try {
    const loaded = yaml.load(yamlText, {
      schema: yaml.DEFAULT_SCHEMA,
      onWarning: () => {
        /* surface via throw path if needed */
      },
    });

    if (loaded === null || loaded === undefined) {
      return {
        ok: true,
        data: {},
        content: afterOpen.slice(closeMatch.index + closeMatch[0].length),
        startLine,
        endLine,
        hasFrontmatter: true,
      };
    }

    if (typeof loaded !== "object" || Array.isArray(loaded)) {
      return {
        ok: false,
        error: "Frontmatter must be a YAML mapping (object)",
        line: startLine + 1,
        hasFrontmatter: true,
      };
    }

    // Prefer gray-matter for body extraction consistency
    let body = afterOpen.slice(closeMatch.index + closeMatch[0].length);
    try {
      const gm = matter(source);
      body = gm.content;
    } catch {
      // keep body from manual split
    }

    return {
      ok: true,
      data: loaded as Record<string, unknown>,
      content: body,
      startLine,
      endLine,
      hasFrontmatter: true,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const lineFromYaml = extractYamlLine(message);
    return {
      ok: false,
      error: `Invalid YAML frontmatter: ${message}`,
      line: lineFromYaml !== undefined ? startLine + lineFromYaml : startLine + 1,
      hasFrontmatter: true,
    };
  }
}

function extractYamlLine(message: string): number | undefined {
  // js-yaml: "at line 3, column 1:" or "(3:1)"
  const m =
    message.match(/at line (\d+)/i) ??
    message.match(/\((\d+):\d+\)/) ??
    message.match(/line (\d+)/i);
  if (!m) return undefined;
  return Number(m[1]);
}

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}
